const rows = $input.all();
const settings = {};
for (const row of rows) {
  if (row.json.key) settings[row.json.key] = row.json.value;
}
const locked = settings['followup_scheduler_locked'] === 'true';
const lockTime = settings['followup_scheduler_lock_time'] || '';
const staleMinutes = parseInt(settings['scheduler_stale_lock_minutes'] || '10', 10);
let isStale = false;
if (locked && lockTime) {
  const lockAge = (Date.now() - new Date(lockTime).getTime()) / 60000;
  isStale = lockAge > staleMinutes;
}
return [{ json: { settings, locked, isStale, lockTime } }];

const dbRows = $('Read Database Sheet').all().map(i => i.json);
const accountRows = $('Read Accounts Sheet').all().map(i => i.json);
const campaignRows = $('Read Campaigns Sheet').all().map(i => i.json);
const settingsRaw = $('Build Settings Map').first().json.settings;
const now = new Date();

const accountMap = {};
for (const a of accountRows) {
  if (a.account_name) accountMap[a.account_name] = a;
}
const campaignMap = {};
for (const c of campaignRows) {
  if (c.campaign_id) campaignMap[c.campaign_id] = c;
}

const globalDmsLimit = parseInt(settingsRaw['dms_daily_limit'] || '20', 10);
const dmQuota = {};
for (const a of accountRows) {
  if (!a.account_name) continue;
  const limit = parseInt(a.dms_daily_limit || globalDmsLimit, 10);
  const sent = parseInt(a.dms_sent_today || '0', 10);
  dmQuota[a.account_name] = Math.max(0, limit - sent);
}

function claimDM(accountName) {
  if (dmQuota[accountName] === undefined || dmQuota[accountName] <= 0) return false;
  dmQuota[accountName]--;
  return true;
}

function isEligible(row) {
  const account = accountMap[row.sending_account];
  if (!account || account.status !== 'active') return false;
  const campaign = campaignMap[row.campaign_id];
  if (!campaign || campaign.campaign_status !== 'running') return false;
  return true;
}

function bool(v) {
  return v === true || v === 'true' || v === 'TRUE';
}

function personalizeText(template, prospect) {
  if (!template) return '';
  const firstName = (prospect.first_name || '').trim();
  const lastName = (prospect.last_name || '').trim();
  return template
    .replace(/\{\{first_name\}\}/gi, firstName)
    .replace(/\{\{last_name\}\}/gi, lastName)
    .replace(/\{\{full_name\}\}/gi, [firstName, lastName].filter(Boolean).join(' '))
    .replace(/\{\{company_name\}\}/gi, (prospect.company_name || '').trim())
    .replace(/\{\{title\}\}/gi, (prospect.title || '').trim());
}

// Part A: message_1 dispatch
const partA = [];
for (const row of dbRows) {
  if (!bool(row.message_1_eligible)) continue;
  if (bool(row.message_1_sent)) continue;
  if (row.lifecycle_state !== 'invite_accepted') continue;
  if (!isEligible(row)) continue;
  if (!claimDM(row.sending_account)) continue;
  const campaignA = campaignMap[row.campaign_id];
  partA.push({ ...row, _account: accountMap[row.sending_account], _campaign: campaignA, _personalized_message_1: personalizeText(campaignA.message_1 || '', row) });
}

// Part B: follow-up 1
const partB = [];
for (const row of dbRows) {
  if (row.lifecycle_state !== 'waiting_for_followup') continue;
  if (bool(row.message_2_sent) || bool(row.reply_received)) continue;
  if (!isEligible(row)) continue;
  const campaign = campaignMap[row.campaign_id];
  const elapsed = (now - new Date(row.message_1_time)) / 3600000;
  if (elapsed < parseFloat(campaign.message_2_delay_hours || 24)) continue;
  if (!claimDM(row.sending_account)) continue;
  partB.push({ ...row, _account: accountMap[row.sending_account], _campaign: campaign, _personalized_message_2: personalizeText(campaign.message_2 || '', row) });
}

// Part C: follow-up 2
const partC = [];
for (const row of dbRows) {
  if (row.lifecycle_state !== 'followup_1_sent') continue;
  if (bool(row.message_3_sent) || bool(row.reply_received)) continue;
  if (!isEligible(row)) continue;
  const campaign = campaignMap[row.campaign_id];
  const elapsed = (now - new Date(row.message_2_time)) / 3600000;
  if (elapsed < parseFloat(campaign.message_3_delay_hours || 48)) continue;
  if (!claimDM(row.sending_account)) continue;
  partC.push({ ...row, _account: accountMap[row.sending_account], _campaign: campaign, _personalized_message_3: personalizeText(campaign.message_3 || '', row) });
}

// Part D: post-followup2 completion
const postWait = parseFloat(settingsRaw['post_followup2_wait_hours'] || '72');
const partD = dbRows.filter(r => {
  if (r.lifecycle_state !== 'followup_2_sent') return false;
  if (bool(r.reply_received)) return false;
  return (now - new Date(r.message_3_time)) / 3600000 >= postWait;
});

// Part E: campaign auto-completion
const activeStates = ['ready_for_invite','invite_sent','invite_accepted','waiting_for_followup','followup_1_sent','followup_2_sent'];
const completableCampaigns = campaignRows.filter(c => {
  if (c.campaign_status !== 'running') return false;
  return !dbRows.some(r => r.campaign_id === c.campaign_id && activeStates.includes(r.lifecycle_state));
});

return [{ json: { partA, partB, partC, partD, completableCampaigns, accountMap, campaignMap, settings: settingsRaw, now: now.toISOString() } }];

// Spreads partA rows for per-item HTTP processing.
// Outputs skip sentinel if partA is empty so the sequential chain continues.
const data = $input.first().json;
if (!data.partA || data.partA.length === 0) {
  return [{ json: { _skip: true } }];
}
return data.partA.map(r => ({ json: r }));

// All Part A processing complete (skip OR success/failure items).
// Collapse to 1 item so Part B is triggered exactly once.
return [{ json: $('Build Work Queues').first().json }];

// Triggered by Part A Gate (sequential execution).
// Reads queue from Build Work Queues directly.
const data = $('Build Work Queues').first().json;
if (!data.partB || data.partB.length === 0) {
  return [{ json: { _skip: true } }];
}
return data.partB.map(r => ({ json: r }));

// Triggered by Part B Gate (sequential execution).
const data = $('Build Work Queues').first().json;
if (!data.partC || data.partC.length === 0) {
  return [{ json: { _skip: true } }];
}
return data.partC.map(r => ({ json: r }));

// Triggered by Part C Gate (sequential execution).
const data = $('Build Work Queues').first().json;
if (!data.partD || data.partD.length === 0) {
  return [{ json: { _skip: true } }];
}
return data.partD.map(r => ({ json: r }));

// Triggered by Part D Gate (sequential execution).
const data = $('Build Work Queues').first().json;
if (!data.completableCampaigns || data.completableCampaigns.length === 0) {
  return [{ json: { _skip: true } }];
}
return data.completableCampaigns.map(c => ({ json: c }));

